query CurrentCrossSellCatalogue {
  products(first: 250) {
    pageInfo {
      hasNextPage
      endCursor
    }
    nodes {
      id
      title
      status
      productType
      vendor
      totalInventory
      variants(first: 100) {
        nodes {
          id
          title
          price
          inventoryQuantity
          inventoryItem {
            tracked
          }
        }
      }
    }
  }
}

query HighReturnProductContent($ids: [ID!]!) {
  nodes(ids: $ids) {
    ... on Product {
      id
      title
      status
      descriptionHtml
      totalInventory
      images(first: 20) {
        nodes {
          id
          altText
          width
          height
        }
      }
      variants(first: 100) {
        nodes {
          id
          title
          price
          inventoryQuantity
          inventoryItem {
            tracked
          }
        }
      }
    }
  }
}

